页面的代码跟踪还不支持指针，这里用数组模拟链表：结点 i 存的就是 ai，`nxt[i]` 是它的 next，0 号是头结点，`nxt[i] == 0` 表示 NULL。代码和指针版一行对一行。n = 6，走到两处会停下来问你。

```trace
id: tr-list
title: n = 6 跟一遍
pointers: p, q, r, s
predict: 9 -> q; 18 -> q
code:
void change_list(int nxt[], int h){
    int p, q, r, s;
    p = h; q = h;
    while(nxt[q] != 0){
        p = nxt[p];
        q = nxt[q];
        if(nxt[q] != 0) q = nxt[q];
    }
    q = nxt[p];
    nxt[p] = 0;
    while(q != 0){
        r = nxt[q];
        nxt[q] = nxt[p];
        nxt[p] = q;
        q = r;
    }
    s = nxt[h];
    q = nxt[p];
    nxt[p] = 0;
    while(q != 0){
        r = nxt[q];
        nxt[q] = nxt[s];
        nxt[s] = q;
        s = nxt[q];
        q = r;
    }
}
int main(){
    int nxt[7] = {1, 2, 3, 4, 5, 6, 0};
    int i;
    change_list(nxt, 0);
    for(i = nxt[0]; i != 0; i = nxt[i])
        printf("%d ", i);
    return 0;
}
```

